        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    productivity: 50,
                    benchStrength: 50,
                    clientSatisfaction: 50,
                    engagement: 50,
                    composite: 50,
                    productivityHistory: [],
                    benchHistory: [],
                    clientSatHistory: [],
                    engagementHistory: [],
                    compositeHistory: []
                };
                this._dsSnaps = [JSON.parse(JSON.stringify(state.domainState))];
            } else {
                var h = (state.history || []).length;
                if (this._dsSnaps.length > h + 1 && this._dsSnaps[h]) {
                    var snap = JSON.parse(JSON.stringify(this._dsSnaps[h]));
                    var ds = state.domainState;
                    for (var k in ds) { if (!(k in snap)) delete ds[k]; }
                    for (var k2 in snap) { ds[k2] = snap[k2]; }
                    this._dsSnaps = this._dsSnaps.slice(0, h + 1);
                }
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    d1: '',
                    d2: '',
                    d3: '',
                    d4: ''
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var d1El = document.getElementById('d1Input');
            var d2El = document.getElementById('d2Input');
            var d3El = document.getElementById('d3Input');
            var d4El = document.getElementById('d4Input');

            if (d1El) decisions.d1 = d1El.value;
            if (d2El) decisions.d2 = d2El.value;
            if (d3El) decisions.d3 = d3El.value;
            if (d4El) decisions.d4 = d4El.value;

            if (!decisions.d1 || !decisions.d2 || !decisions.d3 || !decisions.d4) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('validation_warning'), 'warning'
                );
                return false;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var deltas = { productivity: 0, benchStrength: 0, clientSatisfaction: 0, engagement: 0 };

            var decisionKeys = ['d1', 'd2', 'd3', 'd4'];
            for (var i = 0; i < 4; i++) {
                var choice = d[decisionKeys[i]];
                var impacts = round.decisions[i].impacts[choice];
                if (impacts) {
                    deltas.productivity += impacts.productivity || 0;
                    deltas.benchStrength += impacts.benchStrength || 0;
                    deltas.clientSatisfaction += impacts.clientSatisfaction || 0;
                    deltas.engagement += impacts.engagement || 0;
                }
            }

            state.domainState.productivity = Math.max(0, Math.min(100, state.domainState.productivity + deltas.productivity));
            state.domainState.benchStrength = Math.max(0, Math.min(100, state.domainState.benchStrength + deltas.benchStrength));
            state.domainState.clientSatisfaction = Math.max(0, Math.min(100, state.domainState.clientSatisfaction + deltas.clientSatisfaction));
            state.domainState.engagement = Math.max(0, Math.min(100, state.domainState.engagement + deltas.engagement));

            var composite = Math.round(
                state.domainState.productivity * 0.25 +
                state.domainState.benchStrength * 0.30 +
                state.domainState.clientSatisfaction * 0.25 +
                state.domainState.engagement * 0.20
            );
            state.domainState.composite = composite;

            state.domainState.productivityHistory.push(state.domainState.productivity);
            state.domainState.benchHistory.push(state.domainState.benchStrength);
            state.domainState.clientSatHistory.push(state.domainState.clientSatisfaction);
            state.domainState.engagementHistory.push(state.domainState.engagement);
            state.domainState.compositeHistory.push(composite);

            // platform score mirrors composite because composite is already the 0 to 100
            // weighted metric that getPerformanceSummary uses for the final verdict
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(composite))) });

            this._dsSnaps[state.currentPeriod] = JSON.parse(JSON.stringify(state.domainState));

            if (state.currentPeriod < this.ROUNDS.length) {
                this._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }
            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (eventPanel && eventText && round.eventKey) {
                eventText.innerHTML = window.mySimulation.t(round.eventKey);
                eventPanel.style.display = 'block';
            }

            return {
                period: state.currentPeriod,
                d1: d.d1,
                d2: d.d2,
                d3: d.d3,
                d4: d.d4,
                productivity: state.domainState.productivity,
                benchStrength: state.domainState.benchStrength,
                clientSatisfaction: state.domainState.clientSatisfaction,
                engagement: state.domainState.engagement,
                composite: composite,
                deltaProductivity: deltas.productivity,
                deltaBench: deltas.benchStrength,
                deltaClientSat: deltas.clientSatisfaction,
                deltaEngagement: deltas.engagement
            };
        }

