        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            var lastRecord = history[history.length - 1];
            var results = lastRecord.results || {};
            var composite = results.composite || 0;
            var productivity = results.productivity || 0;
            var bench = results.benchStrength || 0;
            var clientSat = results.clientSatisfaction || 0;
            var engagement = results.engagement || 0;

            var performance = t('perf_developing');
            if (composite >= 70 && bench >= 60) performance = t('perf_strategic');
            else if (composite >= 60) performance = t('perf_competent');
            else if (composite >= 50) performance = t('perf_developing');
            else performance = t('perf_needs_rethink');

            var insights = [];
            if (bench >= 65) insights.push(t('insight_bench_strong'));
            if (bench < 40) insights.push(t('insight_bench_low'));
            if (productivity >= 70 && bench < 45) insights.push(t('insight_productivity_trap'));
            if (composite >= 65) insights.push(t('insight_balanced'));
            if (engagement < 40) insights.push(t('insight_engagement_low'));
            if (clientSat >= 65) insights.push(t('insight_clientsat_strong'));
            if (insights.length === 0) insights.push(t('insight_review'));

            return {
                composite: composite,
                productivity: productivity,
                benchStrength: bench,
                clientSatisfaction: clientSat,
                engagement: engagement,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.deltaBench < -10) return window.mySimulation.t('hint_bench_drop');
            if (results.deltaProductivity > 15 && results.deltaBench < -5) return window.mySimulation.t('hint_productivity_trap');
            if (results.deltaEngagement < -8) return window.mySimulation.t('hint_engagement_drop');
            if (results.composite >= 65) return window.mySimulation.t('hint_balanced');
            if (state.domainState.benchStrength < 35) return window.mySimulation.t('hint_bench_critical');
            return null;
        }

